import {pageDisplayLayers} from './page-layer-view.js?v=20261025-release1';
import {canvasDisplay,elementPoint,elementScreen} from './canvas-coordinates.js?v=20261025-release1';
export function createNavigator(){const panel=document.createElement('section');panel.id='navigatorPanel';panel.innerHTML=`<canvas id="navigatorCanvas" width="220" height="250" aria-label="페이지 네비게이터"></canvas><div class="navigator-controls">
 <div class="navigator-row"><input id="navZoomSlider" type="range" min="10" max="200" step="1" aria-label="네비게이터 확대 비율"><output id="navZoomValue"></output><button id="navZoomOut" title="축소" aria-label="축소">−</button><button id="navZoomIn" title="확대" aria-label="확대">＋</button><button id="navActual" title="100% 원래 크기" aria-label="100% 원래 크기">1:1</button><button id="navFit" title="화면 너비에 맞춤" aria-label="화면 너비에 맞춤">▣</button></div>
 <div class="navigator-row"><input id="navAngleSlider" type="range" min="-180" max="180" step="1" aria-label="네비게이터 회전 각도"><output id="navAngle">0°</output><button id="navRotateLeft" title="왼쪽으로 15도 회전" aria-label="왼쪽으로 회전">↶</button><button id="navRotateRight" title="오른쪽으로 15도 회전" aria-label="오른쪽으로 회전">↷</button><button id="navUpright" title="회전 0도로 복원" aria-label="회전 초기화">↥</button><button id="navFlip" aria-pressed="false" title="캔버스 좌우 반전" aria-label="캔버스 좌우 반전">↔</button></div><button id="navReset" title="회전과 반전 초기화">보기 초기화</button></div>`;return panel;}
export function setupNavigator({getZoom,changeZoom,layout}){
 const $=id=>document.getElementById(id),cv=$('navigatorCanvas'),paper=$('paper'),viewport=$('viewport');let queued=0,rect;
 function paint(){queued=0;if(document.querySelector('canvas[data-drawing]'))return;const w=paper.clientWidth,h=paper.clientHeight;if(!w||!h)return;const ctx=cv.getContext('2d'),k=Math.min((cv.width-12)/w,(cv.height-12)/h);rect={x:(cv.width-w*k)/2,y:(cv.height-h*k)/2,w:w*k,h:h*k};ctx.clearRect(0,0,cv.width,cv.height);ctx.fillStyle='#fff';ctx.fillRect(rect.x,rect.y,rect.w,rect.h);
  const composite=paper.querySelector('.page-composite'),displays=pageDisplayLayers(paper);if(composite)ctx.drawImage(composite,rect.x,rect.y,rect.w,rect.h);for(const src of composite?[]:displays){ctx.save();ctx.globalAlpha=Number(src.style.opacity);ctx.globalCompositeOperation=src.dataset.blend||'source-over';ctx.drawImage(src,rect.x+src.offsetLeft*k,rect.y+src.offsetTop*k,src.clientWidth*k,src.clientHeight*k);ctx.restore();}
  if(!displays.length)for(const wrap of paper.querySelectorAll('.panel-wrap')){if(wrap.hidden)continue;const src=wrap.querySelector('canvas');if(src?.width)ctx.drawImage(src,rect.x+wrap.offsetLeft*k,rect.y+wrap.offsetTop*k,wrap.clientWidth*k,wrap.clientHeight*k);}
  for(const plane of paper.querySelectorAll('.balloon-plane'))for(const src of plane.querySelectorAll('canvas'))ctx.drawImage(src,rect.x+(plane.offsetLeft+src.offsetLeft)*k,rect.y+(plane.offsetTop+src.offsetTop)*k,src.clientWidth*k,src.clientHeight*k);
  const v=viewport.getBoundingClientRect();ctx.save();ctx.beginPath();ctx.rect(rect.x,rect.y,rect.w,rect.h);ctx.clip();ctx.beginPath();[[v.left,v.top],[v.right,v.top],[v.right,v.bottom],[v.left,v.bottom]].forEach(([clientX,clientY],i)=>{const p=elementPoint(paper,{clientX,clientY});ctx[i?'lineTo':'moveTo'](rect.x+p[0]*rect.w,rect.y+p[1]*rect.h);});ctx.closePath();ctx.strokeStyle='#eb6b6b';ctx.lineWidth=1.5;ctx.stroke();ctx.restore();$('navZoomValue').textContent=Math.round(getZoom()*100)+'%';$('navZoomSlider').value=Math.round(getZoom()*100);$('navAngleSlider').value=canvasDisplay.angle;$('navAngle').textContent=canvasDisplay.angle+'°';$('navFlip').setAttribute('aria-pressed',String(canvasDisplay.flip));
 }
 const queue=()=>{if(!queued)queued=requestAnimationFrame(paint);};
 function transform(angle,flip){const v=viewport.getBoundingClientRect(),center={clientX:v.left+v.width/2,clientY:v.top+v.height/2},p=elementPoint(paper,center);canvasDisplay.angle=angle;canvasDisplay.flip=flip;paper.style.transform=`rotate(${angle}deg) scaleX(${flip?-1:1})`;layout();const q=elementScreen(paper,p);viewport.scrollLeft+=q[0]-center.clientX;viewport.scrollTop+=q[1]-center.clientY;queue();}
 $('navZoomIn').onclick=()=>changeZoom(getZoom()+.1);$('navZoomOut').onclick=()=>changeZoom(getZoom()-.1);$('navFit').onclick=()=>$('fitWidth').click();$('navRotateLeft').onclick=()=>transform((canvasDisplay.angle-15)%360,canvasDisplay.flip);$('navRotateRight').onclick=()=>transform((canvasDisplay.angle+15)%360,canvasDisplay.flip);$('navFlip').onclick=()=>transform(canvasDisplay.angle,!canvasDisplay.flip);$('navReset').onclick=()=>transform(0,false);
 $('navZoomSlider').oninput=e=>changeZoom(+e.target.value/100);$('navAngleSlider').oninput=e=>transform(+e.target.value,canvasDisplay.flip);$('navActual').onclick=()=>changeZoom(1);$('navUpright').onclick=()=>transform(0,canvasDisplay.flip);
 const move=e=>{if(!rect)return;const r=cv.getBoundingClientRect(),p=[((e.clientX-r.left)/r.width*cv.width-rect.x)/rect.w,((e.clientY-r.top)/r.height*cv.height-rect.y)/rect.h],q=elementScreen(paper,p.map(n=>Math.max(0,Math.min(1,n)))),v=viewport.getBoundingClientRect();viewport.scrollLeft+=q[0]-v.left-v.width/2;viewport.scrollTop+=q[1]-v.top-v.height/2;queue();};let dragging=false;
 cv.onpointerdown=e=>{dragging=true;cv.setPointerCapture(e.pointerId);move(e);};cv.onpointermove=e=>{if(dragging)move(e);};cv.onpointerup=cv.onpointercancel=()=>dragging=false;
 viewport.addEventListener('scroll',queue);document.addEventListener('canvas-painted',queue);document.addEventListener('page-composited',queue);document.addEventListener('drawing-ended',queue);new ResizeObserver(queue).observe(paper);new ResizeObserver(()=>{const r=cv.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2),w=Math.max(1,Math.round(r.width*dpr)),h=Math.max(1,Math.round(r.height*dpr));if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h;queue();}}).observe(cv);queue();return {queue};
}
